blocks.content:
1* {
2    margin: 0;
3    padding: 0;
4    box-sizing: border-box;
5}
6
7body {
8    font-family: Arial, sans-serif;
9    color: #333;
10}
11
12.navbar {
13    display: flex;
14    justify-content: space-between;
15    padding: 1rem;
16    background: black;
17}
18
19.logo {
20    font-size: 1.5rem;
21    font-weight: bold;
22    color: white;
23}
24
25.nav-links {
26    display: none;
27}
28
29.icon {
30    color: white;
31    font-size: 1.5rem;
32}
33
34/* For medium screen sizes */
35@media (min-width: 601px) {
36
37    .navbar {
38        flex-direction: row;
39    }
40
41    .nav-links {
42        display: flex;
43        list-style: none;
44        gap: 2rem;
45    }
46
47    .nav-links a {
48        color: white;
49        text-decoration: none;
50        font-size: 1rem;
51    }
52
53    .icon {
54        display: none;
55    }
56}
57
